import{_ as d,o,c as r,a3 as a}from"./chunks/framework.CqzWVxDX.js";const e="/ems_simulate/assets/modbus-add.BFfy8vR7.png",l="/ems_simulate/assets/modbus-operation.BUQIYPW_.png",s="/ems_simulate/assets/modbus-parameter.D5b6h6kU.png",g=JSON.parse('{"title":"Modbus 操作指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/modbus/operation.md","filePath":"guide/protocols/modbus/operation.md","lastUpdated":1786981506000}'),i={name:"guide/protocols/modbus/operation.md"};function n(h,t,u,b,c,m){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="modbus-操作指南" tabindex="-1">Modbus 操作指南 <a class="header-anchor" href="#modbus-操作指南" aria-label="Permalink to &quot;Modbus 操作指南&quot;">​</a></h1><h2 id="一、前置条件" tabindex="-1">一、前置条件 <a class="header-anchor" href="#一、前置条件" aria-label="Permalink to &quot;一、前置条件&quot;">​</a></h2><ul><li>已安装并启动 EMS Simulate（见<a href="./../../install/getting-started.html">快速开始</a>）；</li><li><strong>服务端模拟</strong>：无需外部设备，电脑本机即可完成全流程演示；</li><li><strong>客户端模式</strong>：需要一台可访问的真实 Modbus 从站（或使用本软件再模拟一台服务端）。</li></ul><h2 id="二、服务端模式-模拟从站" tabindex="-1">二、服务端模式（模拟从站） <a class="header-anchor" href="#二、服务端模式-模拟从站" aria-label="Permalink to &quot;二、服务端模式（模拟从站）&quot;">​</a></h2><p><strong>目标</strong>：用 EMS Simulate 模拟一个 Modbus 从站，监听端口/串口并响应主站请求。</p><h3 id="步骤-1-添加设备" tabindex="-1">步骤 1：添加设备 <a class="header-anchor" href="#步骤-1-添加设备" aria-label="Permalink to &quot;步骤 1：添加设备&quot;">​</a></h3><ol><li>在左侧设备树区域点击&quot;<strong>添加设备</strong>&quot;；</li><li>填写设备名称（如 <code>Modbus 模拟从站</code>）；</li><li>选择协议 <strong>Modbus TCP</strong> 或 <strong>Modbus RTU</strong>；</li><li>连接方式选择 <strong>服务端（Server）</strong>；</li><li>按下表配置连接参数并保存：</li></ol><table tabindex="0"><thead><tr><th>参数</th><th>TCP</th><th>RTU</th></tr></thead><tbody><tr><td>IP / 端口</td><td>监听 IP（默认 <code>0.0.0.0</code>）、端口（默认 502）</td><td>—</td></tr><tr><td>串口</td><td>—</td><td>串口号（如 COM1）</td></tr><tr><td>波特率</td><td>—</td><td>默认 9600</td></tr><tr><td>数据位 / 校验 / 停止位</td><td>—</td><td>8 / N / 1（可调）</td></tr></tbody></table><p><img src="'+e+'" alt=""></p><h3 id="步骤-2-添加测点" tabindex="-1">步骤 2：添加测点 <a class="header-anchor" href="#步骤-2-添加测点" aria-label="Permalink to &quot;步骤 2：添加测点&quot;">​</a></h3><p>进入设备详情，点击&quot;<strong>添加测点</strong>&quot;，按下表配置：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>测点类型</td><td>YC 遥测 / YX 遥信 / YK 遥控 / YT 遥调</td><td>遥测</td></tr><tr><td>地址</td><td>寄存器/线圈地址</td><td><code>0x0000</code></td></tr><tr><td>功能码</td><td>对应数据区</td><td><code>03 - 读保持寄存器</code></td></tr><tr><td>解析码</td><td>数据格式（字节序）</td><td><code>0x42 - Float AB CD</code></td></tr><tr><td>乘法系数 / 加法系数</td><td>原始值 → 真实值换算</td><td>0.1 / 0</td></tr><tr><td>编码 / 名称</td><td>测点唯一标识</td><td><code>YC_001</code> / 电池电压</td></tr></tbody></table><blockquote><p>💡 批量配置方式：</p><ul><li><strong>Excel 点表导入</strong>：准备含地址/功能码/解析码的 xlsx 表格，一键导入；</li><li><strong>设备批量复制</strong>：右键已有设备&quot;复制&quot;，支持前缀后缀、IP 偏移、端口偏移，快速复制整套测点。</li></ul></blockquote><h3 id="步骤-3-启动设备" tabindex="-1">步骤 3：启动设备 <a class="header-anchor" href="#步骤-3-启动设备" aria-label="Permalink to &quot;步骤 3：启动设备&quot;">​</a></h3><p>点击设备卡片上的&quot;<strong>开启设备</strong>&quot;，服务端开始监听。此时用任意 Modbus 主站工具（或本软件的客户端模式）即可访问。</p><h3 id="步骤-4-验证" tabindex="-1">步骤 4：验证 <a class="header-anchor" href="#步骤-4-验证" aria-label="Permalink to &quot;步骤 4：验证&quot;">​</a></h3><ol><li>再添加一台 Modbus <strong>客户端</strong>设备，目标指向服务端（本机 <code>127.0.0.1:502</code> 或对应串口）；</li><li>启动客户端，在测点表格中点击&quot;<strong>读取</strong>&quot;；</li><li>使用&quot;<strong>批量读取</strong>&quot;（合并连续地址一次性读取）或&quot;<strong>自动读取</strong>&quot;（按间隔轮询）验证数据返回；</li><li>在服务端展开测点行，可手动修改真实值，客户端再次读取应看到更新。</li></ol><p><img src="'+l+'" alt=""></p><h2 id="三、客户端模式-读取真实设备" tabindex="-1">三、客户端模式（读取真实设备） <a class="header-anchor" href="#三、客户端模式-读取真实设备" aria-label="Permalink to &quot;三、客户端模式（读取真实设备）&quot;">​</a></h2><ol><li>添加设备时连接方式选择 <strong>客户端（Client）</strong>；</li><li>配置目标：TCP 模式填设备 IP 与端口，RTU 模式填串口参数与从站地址；</li><li>添加测点：地址、功能码、解析码必须与真实从站一致；</li><li>启动后点击&quot;读取 / 批量读取 / 自动读取&quot;获取数据；</li><li>如需写入，展开测点行直接修改真实值（或使用&quot;写入&quot;操作），观察从站是否响应。</li></ol><h2 id="四、协议参数详解" tabindex="-1">四、协议参数详解 <a class="header-anchor" href="#四、协议参数详解" aria-label="Permalink to &quot;四、协议参数详解&quot;">​</a></h2><p>在设备&quot;协议参数&quot;标签页可配置：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>连接超时</td><td>3000ms</td><td>建立 TCP 连接的超时时间</td></tr><tr><td>命令超时</td><td>2000ms</td><td>单条命令等待响应的超时时间</td></tr><tr><td>命令重试次数</td><td>1</td><td>命令失败后的自动重试次数</td></tr><tr><td>重连初始间隔</td><td>2000ms</td><td>断线后首次重连等待时间</td></tr><tr><td>重连最大间隔</td><td>30000ms</td><td>重连等待上限（指数退避）</td></tr><tr><td>最大重连次数</td><td>0</td><td>0 表示不限制</td></tr><tr><td>客户端空闲超时</td><td>0</td><td>服务端断开空闲客户端（0 不超时）</td></tr><tr><td>最大连接数</td><td>0</td><td>服务端同时允许的连接数（0 不限制）</td></tr></tbody></table><p><img src="'+s+'" alt=""></p><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>排查建议</th></tr></thead><tbody><tr><td>客户端连接不上服务端</td><td>确认端口一致、IP 可达、防火墙放行</td></tr><tr><td>读取返回异常值</td><td>检查解析码字节序与设备实际数据格式是否一致</td></tr><tr><td>RTU 无响应</td><td>检查串口号、波特率、从站地址、校验位</td></tr><tr><td>写入不生效</td><td>确认功能码是写操作（05/06/15/16）且地址可写</td></tr></tbody></table><blockquote><p>📄 报文如何解析见 <a href="./packet-view.html">Modbus 报文查看</a>。</p></blockquote>',27)])])}const q=d(i,[["render",n]]);export{g as __pageData,q as default};
